from langfuse.api.scores.types.score_subject_observation_v3 import ScoreSubjectObservationV3

def test_traceid_alias_getter():
    # Construct using the alias field name
    obj = ScoreSubjectObservationV3(id="obs-1", traceId="trace-123")
    assert obj.trace_id == "trace-123"
    # Alias property should return the same value
    assert obj.traceId == "trace-123"

